code_examples.text:
 profile stats my_stats {
   defaults from stats
   field1 tot_users
   field2 cur_users
   field3 max_users
 }

 rule track_users {
   when CLIENT_ACCEPTED { 
     STATS::incr my_stats tot_users 
     STATS::setmax my_stats max_users [STATS::incr my_stats cur_users]
 }
 }

 virtual stats-1 {
   destination 10.10.55.66:http
   ip protocol tcp
   profile http my_stats tcp
   pool pool1
   rule track_users
}
